'use server'

import { refresh } from 'next/cache'

// In-memory store standing in for your database / user record.
// Replace this with a real persistence layer and an authenticated user lookup
// (e.g. `auth()`, `cookies()`, or your DB) in a production app.
type NotificationPreference = {
  notificationsEnabled: boolean
}

const userPreference: NotificationPreference = {
  notificationsEnabled: false,
}

// Reads the current preference so the Server Component can render it.
// This runs on the server; it is NOT a Server Action (no "use server" here).
export function getNotificationPreference(): NotificationPreference {
  return { ...userPreference }
}

// Server Action: toggles the user's notification preference on/off, then
// refreshes the current page so the UI reflects the updated state.
// `refresh()` re-renders the current route on the client router without
// navigating away from the page (no redirect).
export async function toggleNotifications() {
  // Always verify authentication/authorization here in a real app.
  userPreference.notificationsEnabled = !userPreference.notificationsEnabled

  // Refresh the client router from within the Server Action so the
  // current page re-renders with the latest data. This is Next.js's
  // recommended way to refresh the current page after a mutation
  // without redirecting to another route.
  refresh()
}

