args.content:
import {
  getNotificationPreference,
  toggleNotifications,
} from './actions'

export default function Home() {
  const { notificationsEnabled } = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>

      <section>
        <h2>Notifications</h2>
        <p>
          Current preference:{' '}
          <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>
        </p>

        {/* The form's `action` prop invokes the Server Action. After it runs
            and calls `refresh()`, Next.js re-renders the current page in place
            (no navigation/redirect), so the preference below updates. */}
        <form action={toggleNotifications}>
          <button type="submit">
            Turn notifications {notificationsEnabled ? 'off' : 'on'}
          </button>
        </form>
      </section>
    </main>
  )
}

